import{_ as a,o as t,c as i,a2 as o}from"./chunks/framework.BN2sqjC1.js";const h=JSON.parse('{"title":"Segreti e variabili della pipeline di rilascio","description":"","frontmatter":{},"headers":[],"relativePath":"release/secrets.md","filePath":"release/secrets.md"}'),d={name:"release/secrets.md"};function r(n,e,c,s,l,p){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="segreti-e-variabili-della-pipeline-di-rilascio" tabindex="-1">Segreti e variabili della pipeline di rilascio <a class="header-anchor" href="#segreti-e-variabili-della-pipeline-di-rilascio" aria-label="Permalink to &quot;Segreti e variabili della pipeline di rilascio&quot;">​</a></h1><h2 id="cosa-usa-oggi-release-yml" tabindex="-1">Cosa usa oggi <code>release.yml</code> <a class="header-anchor" href="#cosa-usa-oggi-release-yml" aria-label="Permalink to &quot;Cosa usa oggi `release.yml`&quot;">​</a></h2><p>Dalla 1.2.2 <code>release.yml</code> <strong>non legge nessun segreto né variabile del repository</strong>: costruisce e pubblica senza firmare (vedi <a href="./">README.md</a>). Usa solo il <code>GITHUB_TOKEN</code> che GitHub crea per ogni run, con permessi minimi per job:</p><table tabindex="0"><thead><tr><th>Job</th><th>Permessi del <code>GITHUB_TOKEN</code></th><th>Uso</th></tr></thead><tbody><tr><td><code>image</code> (immagine cloud)</td><td><code>contents: read</code>, <code>packages: write</code></td><td>login e push su GHCR (<code>ghcr.io/&lt;owner&gt;/clarae-cloud</code>)</td></tr><tr><td><code>chart</code> (chart Helm)</td><td><code>contents: read</code>, <code>packages: write</code></td><td><code>helm registry login</code> e push OCI su <code>oci://ghcr.io/&lt;owner&gt;/charts</code></td></tr><tr><td><code>desktop</code> (installer)</td><td><code>contents: read</code> (default del file)</td><td>nessun accesso in scrittura; gli installer sono artefatti del run</td></tr><tr><td><code>release</code> (GitHub Release)</td><td><code>contents: write</code></td><td><code>gh release create</code> con installer e <code>SHA256SUMS</code></td></tr></tbody></table><p>Non serve configurare nulla in Settings, Secrets and variables, Actions. I pacchetti GHCR creati al primo push sono privati: renderli pubblici (Package settings, Change visibility) o concedere l&#39;accesso dalle impostazioni del pacchetto; il chart (<code>.../charts/clarae</code>) è un pacchetto separato. <strong>Nessuna chiave o certificato è nel repository</strong> e nessuna è stata generata qui.</p><h2 id="da-riattivare" tabindex="-1">Da riattivare <a class="header-anchor" href="#da-riattivare" aria-label="Permalink to &quot;Da riattivare&quot;">​</a></h2><p>Il resto di questo documento descrive la pipeline firmata di ADR-0023 e il canale non firmato di ADR-0031, com&#39;erano <strong>fino alla 1.2.1</strong>. La 1.2.2 ha tolto da <code>release.yml</code> i passi di firma (Apple, Authenticode), notarizzazione, cosign, SBOM, attestazioni e manifest di aggiornamento: impostare oggi questi segreti <strong>non ha alcun effetto</strong>. Per riattivarli bisogna ripristinare quei passi nel workflow (l&#39;ultima versione completa è quella precedente al commit <code>4631447</code>) e poi configurare i segreti sotto. Il riferimento resta utile per quel lavoro.</p><h3 id="cosa-succedeva-con-o-senza-ciascun-segreto" tabindex="-1">Cosa succedeva con o senza ciascun segreto <a class="header-anchor" href="#cosa-succedeva-con-o-senza-ciascun-segreto" aria-label="Permalink to &quot;Cosa succedeva con o senza ciascun segreto&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Manca</th><th>Effetto (<code>REQUIRE_SIGNING</code> non impostata)</th><th>Con <code>REQUIRE_SIGNING=true</code> su un tag</th></tr></thead><tbody><tr><td><code>APPLE_CERT_P12_BASE64</code> o <code>APPLE_SIGNING_IDENTITY</code></td><td><code>.dmg</code> non firmato né notarizzato: Gatekeeper avvisa (tasto destro, Apri).</td><td>La pipeline fallisce in <code>meta</code>.</td></tr><tr><td><code>APPLE_API_KEY_*</code></td><td><code>.dmg</code> firmato ma non notarizzato (se il resto c&#39;è).</td><td>Come sopra.</td></tr><tr><td><code>WINDOWS_CERT_PFX_BASE64</code></td><td><code>clarae.exe</code> e installer non firmati: SmartScreen avvisa (Ulteriori informazioni, Esegui comunque).</td><td>La pipeline fallisce in <code>meta</code>.</td></tr><tr><td><code>UPDATE_SIGNING_KEY</code> o variabile <code>UPDATE_PUBLIC_KEY</code></td><td>Il desktop è compilato con l&#39;updater <strong>disattivato</strong> (<code>updater.DisabledByBuild</code>) e non si pubblica nessun manifest.</td><td>La pipeline fallisce in <code>meta</code>.</td></tr><tr><td>nessuno dei precedenti</td><td>Release in prerelease &quot;unsigned&quot;, bozza (vedi <code>RELEASE_AUTO_PUBLISH</code>). Le immagini Docker restano firmate (cosign è keyless).</td><td>La pipeline fallisce in <code>meta</code>.</td></tr></tbody></table><h3 id="variabili-pubbliche-tab-variables" tabindex="-1">Variabili (pubbliche, tab Variables) <a class="header-anchor" href="#variabili-pubbliche-tab-variables" aria-label="Permalink to &quot;Variabili (pubbliche, tab Variables)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nome</th><th>Uso</th></tr></thead><tbody><tr><td><code>UPDATE_PUBLIC_KEY</code></td><td>Chiave pubblica ed25519 (base64) che i client usano per verificare il manifest di aggiornamento; compilata nel binario con ldflags. Senza di essa l&#39;updater è disattivato nella build: <code>build-desktop.sh --release</code> non compila mai con la chiave di sviluppo.</td></tr><tr><td><code>UPDATE_BASE_URL</code></td><td>URL pubblico del canale di aggiornamento (contiene <code>stable/manifest.json</code> e <code>beta/manifest.json</code>, con i <code>.sig</code>). Serve solo con l&#39;updater attivo.</td></tr><tr><td><code>REQUIRE_SIGNING</code></td><td>(opzionale) <code>true</code>: un tag senza tutti i segreti di firma fallisce. Default: canale non firmato.</td></tr><tr><td><code>RELEASE_AUTO_PUBLISH</code></td><td>(opzionale) <code>true</code>: la release è pubblicata subito. Default: bozza, che una persona promuove dopo la checklist su tre sistemi.</td></tr><tr><td><code>ENABLE_ATTESTATIONS</code></td><td>(opzionale) <code>true</code>: pubblica le attestazioni di provenienza GitHub (immagine e file della release). Servono un repository pubblico o un piano che le includa: su un repository privato senza piano il passo fallisce (&quot;Feature not available&quot;). Cosign firma comunque l&#39;immagine.</td></tr><tr><td><code>LINUX_ARM64_RUNNER</code></td><td>(opzionale) etichetta di un runner arm64, es. <code>ubuntu-24.04-arm</code> (gratuito nei repository pubblici). Senza, nessun installer Linux arm64.</td></tr><tr><td><code>WINDOWS_TIMESTAMP_URL</code></td><td>(opzionale) server RFC 3161, default <code>http://timestamp.digicert.com</code>.</td></tr></tbody></table><h3 id="segreti-tab-secrets" tabindex="-1">Segreti (tab Secrets) <a class="header-anchor" href="#segreti-tab-secrets" aria-label="Permalink to &quot;Segreti (tab Secrets)&quot;">​</a></h3><h4 id="manifest-di-aggiornamento-opzionale-senza-niente-aggiornamenti-automatici" tabindex="-1">Manifest di aggiornamento (opzionale: senza, niente aggiornamenti automatici) <a class="header-anchor" href="#manifest-di-aggiornamento-opzionale-senza-niente-aggiornamenti-automatici" aria-label="Permalink to &quot;Manifest di aggiornamento (opzionale: senza, niente aggiornamenti automatici)&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Nome</th><th>Contenuto</th></tr></thead><tbody><tr><td><code>UPDATE_SIGNING_KEY</code></td><td>Chiave <strong>privata</strong> ed25519, base64 (64 byte o seed da 32). Generazione: vedi &quot;Generare la chiave&quot; sotto. Custodire anche una copia offline cifrata.</td></tr></tbody></table><h4 id="macos-firma-e-notarizzazione" tabindex="-1">macOS (firma e notarizzazione) <a class="header-anchor" href="#macos-firma-e-notarizzazione" aria-label="Permalink to &quot;macOS (firma e notarizzazione)&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Nome</th><th>Contenuto</th></tr></thead><tbody><tr><td><code>APPLE_CERT_P12_BASE64</code></td><td>Certificato <strong>Developer ID Application</strong> con chiave privata, esportato in <code>.p12</code>, in base64.</td></tr><tr><td><code>APPLE_CERT_PASSWORD</code></td><td>Password del <code>.p12</code>.</td></tr><tr><td><code>APPLE_SIGNING_IDENTITY</code></td><td>Nome dell&#39;identità, es. <code>Developer ID Application: Nome Cognome (TEAMID)</code>.</td></tr><tr><td><code>APPLE_API_KEY_P8_BASE64</code></td><td>Chiave API App Store Connect (<code>AuthKey_XXXX.p8</code>) in base64, per <code>notarytool</code>.</td></tr><tr><td><code>APPLE_API_KEY_ID</code>, <code>APPLE_API_ISSUER</code></td><td>Key ID e Issuer ID della chiave API.</td></tr></tbody></table><p>Alternativa locale a <code>APPLE_API_*</code>: <code>NOTARY_KEYCHAIN_PROFILE</code> (profilo di <code>xcrun notarytool store-credentials</code>) oppure <code>APPLE_ID</code> + <code>APPLE_APP_PASSWORD</code> + <code>APPLE_TEAM_ID</code> (<code>scripts/release/package-macos.sh</code> accetta tutte e tre le forme).</p><h4 id="windows-authenticode" tabindex="-1">Windows (Authenticode) <a class="header-anchor" href="#windows-authenticode" aria-label="Permalink to &quot;Windows (Authenticode)&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Nome</th><th>Contenuto</th></tr></thead><tbody><tr><td><code>WINDOWS_CERT_PFX_BASE64</code></td><td>Certificato di code signing (OV/EV) con chiave privata in <code>.pfx</code>, base64.</td></tr><tr><td><code>WINDOWS_CERT_PASSWORD</code></td><td>Password del <code>.pfx</code>.</td></tr></tbody></table><p>Un certificato EV su token hardware non è utilizzabile da un runner ospitato da GitHub: serve un runner self-hosted o un servizio di firma in cloud (in quel caso definire direttamente <code>CLARAE_SIGNTOOL_CMD</code>, vedi <code>build/windows/installer/project.nsi</code>).</p><h4 id="immagini-oci-e-chart-helm" tabindex="-1">Immagini OCI e chart Helm <a class="header-anchor" href="#immagini-oci-e-chart-helm" aria-label="Permalink to &quot;Immagini OCI e chart Helm&quot;">​</a></h4><p>Nessun segreto aggiuntivo: la firma <code>cosign</code> era <strong>keyless</strong> (identità OIDC del workflow, permesso <code>id-token: write</code>, oggi non concesso) e il push su GHCR usa <code>GITHUB_TOKEN</code> (<code>packages: write</code>), come oggi.</p><h3 id="generare-la-chiave-del-manifest" tabindex="-1">Generare la chiave del manifest <a class="header-anchor" href="#generare-la-chiave-del-manifest" aria-label="Permalink to &quot;Generare la chiave del manifest&quot;">​</a></h3><p>Su una macchina fidata, offline (il tool stampa solo su stdout, non scrive file):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release-tool</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bin/release</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gen-key</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # private -&gt; segreto UPDATE_SIGNING_KEY, public -&gt; variabile UPDATE_PUBLIC_KEY</span></span></code></pre></div><p>Salvare la chiave privata in un password manager o in un HSM/vault e tenerne una copia offline cifrata. Per ricavare la pubblica da una privata esistente: <code>CLARAE_UPDATE_SIGNING_KEY=... bin/release pubkey</code>. Prima di impostare i segreti verificare la coppia: <code>bin/release gen-manifest ... &amp;&amp; bin/release sign-manifest -in manifest.json &amp;&amp; bin/release verify-manifest -in manifest.json -pubkey &lt;pubblica&gt;</code>.</p><h3 id="chiave-di-sviluppo" tabindex="-1">Chiave di sviluppo <a class="header-anchor" href="#chiave-di-sviluppo" aria-label="Permalink to &quot;Chiave di sviluppo&quot;">​</a></h3><p>Senza <code>UPDATE_PUBLIC_KEY</code> una build locale si fida della chiave di sviluppo, derivata da una frase pubblica (<code>internal/updater/key.go</code>): <strong>chiunque</strong> può firmare manifest accettati da quei binari. Va bene per test locali, mai per build distribuite: per questo <code>--release</code> fallisce, a meno di <code>ALLOW_UNSIGNED_UPDATES=1</code> (la pipeline lo imposta quando mancano le chiavi), che compila l&#39;updater <strong>fuori</strong> dal binario.</p><h3 id="rotazione-e-compromissione" tabindex="-1">Rotazione e compromissione <a class="header-anchor" href="#rotazione-e-compromissione" aria-label="Permalink to &quot;Rotazione e compromissione&quot;">​</a></h3><p>Vedi <a href="./">README.md</a>, sezione «Ruotare la chiave di aggiornamento».</p>',30)])])}const m=a(d,[["render",r]]);export{h as __pageData,m as default};
